anet = an.AnnNet(directed=True)
anet.add_nodes(['A', 'B', 'C', 'D', 'E'])
anet.add_edges('A', 'B', edge_id='binary_edge', weight=1.0)
anet.add_edges('A', 'B', edge_id='parallel_edge', weight=0.65)
anet.add_edges('B', 'C', edge_id='complex_edge', directed=False, weight=0.8)
