anet.attrs.update(
    'nodes',
    {
        'A': {'label': 'ligand'},
        'B': {'label': 'enzyme'},
        'C': {'label': 'cofactor'},
        'D': {'label': 'product'},
        'E': {'label': 'byproduct'},
    },
)

anet.attrs.table('edges', derived=True).select(
    ['edge_id', 'kind', 'source', 'target', 'head', 'tail']
)
